package cn.haiduo;
import cn.haiduo.platform.*;
import com.fasterxml.jackson.databind.*;
import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ShopifyAdapterTest {
 @Test void oversizedResponseIsRejectedDuringStreaming()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{byte[] body=new byte[2097153];e.sendResponseHeaders(200,body.length);try{e.getResponseBody().write(body);}catch(java.io.IOException ignored){}finally{e.close();}});server.start();try{assertThrows(IllegalStateException.class,()->new ShopifyHttp().post(URI.create("http://127.0.0.1:"+server.getAddress().getPort()),Map.of(),"{}"));}finally{server.stop(0);}}
 @Test void rawSignatureEncryptionAndHostValidation(){String secret="test-secret";byte[] raw="{\"id\":1}".getBytes(StandardCharsets.UTF_8);String signature=Base64.getEncoder().encodeToString(PlatformCrypto.hmac(secret,raw));assertTrue(PlatformCrypto.webhook(secret,raw,signature));assertFalse(PlatformCrypto.webhook(secret,"{ \"id\":1 }".getBytes(StandardCharsets.UTF_8),signature));assertFalse(PlatformCrypto.webhook(secret,raw,"bad"));String key=Base64.getEncoder().encodeToString(new byte[32]);String encrypted=PlatformCrypto.encrypt(key,"test-access-token");assertNotEquals("test-access-token",encrypted);assertEquals("test-access-token",PlatformCrypto.decrypt(key,encrypted));assertNotEquals(encrypted,PlatformCrypto.encrypt(key,"test-access-token"));assertEquals("shop.myshopify.com",ShopifyConnector.validShop("SHOP.myshopify.com"));assertThrows(IllegalArgumentException.class,()->ShopifyConnector.validShop("shop.myshopify.com.evil"));assertThrows(IllegalArgumentException.class,()->ShopifyConnector.validShop("localhost"));}
 @Test void graphQlPaginationAnd429RetryViaHttp()throws Exception{var mapper=new ObjectMapper();var calls=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/graphql",e->{int call=calls.incrementAndGet();if(!"test-token".equals(e.getRequestHeaders().getFirst("X-Shopify-Access-Token"))){e.sendResponseHeaders(401,-1);e.close();return;}if(call==1){e.getResponseHeaders().add("Retry-After","0");e.sendResponseHeaders(429,-1);e.close();return;}JsonNode request=mapper.readTree(e.getRequestBody());boolean first=request.path("variables").path("cursor").isNull();Map<String,Object> item=Map.of("quantity",1,"sku","DEMO-BAG","variant",Map.of("id","gid://shopify/ProductVariant/1"));Map<String,Object> order=new HashMap<>();order.put("id","gid://shopify/Order/"+(first?1:2));order.put("updatedAt","2026-11-01T00:00:00Z");order.put("cancelledAt",null);order.put("displayFinancialStatus","PAID");order.put("currentSubtotalPriceSet",Map.of("presentmentMoney",Map.of("amount","100.00","currencyCode","USD")));order.put("lineItems",Map.of("nodes",List.of(item),"pageInfo",Map.of("hasNextPage",false)));byte[] body=mapper.writeValueAsBytes(Map.of("data",Map.of("orders",Map.of("nodes",List.of(order),"pageInfo",Map.of("hasNextPage",first,"endCursor","page-1")))));e.getResponseHeaders().add("Content-Type","application/json");e.sendResponseHeaders(200,body.length);e.getResponseBody().write(body);e.close();});server.start();try{var connector=new ShopifyConnector(URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/graphql"),"test-token",new ShopifyHttp());var orders=connector.orders();assertEquals(2,orders.size());assertEquals(3,calls.get());assertEquals(new BigDecimal("100.00"),orders.getFirst().net());assertEquals("USD",orders.getFirst().currency());assertEquals("PAID",orders.getFirst().payment());assertNotEquals(orders.getFirst().externalId(),orders.getLast().externalId());}finally{server.stop(0);}}
 @Test void retriesAreBounded()throws Exception{var calls=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{calls.incrementAndGet();e.sendResponseHeaders(503,-1);e.close();});server.start();try{assertThrows(IllegalStateException.class,()->new ShopifyHttp().post(URI.create("http://127.0.0.1:"+server.getAddress().getPort()),Map.of(),"{}"));assertEquals(3,calls.get());}finally{server.stop(0);}}
}
